def duties():
    for context, skill, age, source in DUTIES:
        for line in source.strip().splitlines():
            title, action, trigger = line.split('|')
            ROWS.append(dict(id=f'A{len(ROWS)+1:03}', catalog='duties', title=title,
                context=context, age=age, tone='Pflicht mit positiver und Konfliktvariante',
                description=f'A {action}. B kann zustimmen, Unterstützung anbieten oder wegen eigener Verpflichtungen um einen anderen Zeitpunkt bitten.',
                trigger=trigger+'; A kennt die Aufgabe, ist zuständig und hat einen erreichbaren Ort sowie die erforderlichen sicheren Mittel.',
                resolution='Erledigen, freiwillig aufteilen, neu terminieren oder begründet ablehnen. Nur tatsächlich vollendete Schritte zählen; bei fehlenden Mitteln wird Hilfe angefragt statt Erfolg erfunden.',
                effects=f'{title} verändert den zugehörigen Aufgabenstand und ggf. das konkrete Objekt. Zuverlässigkeit, Entlastung und Nähe steigen bei fairer Kooperation; unbegründete Vorwürfe oder gebrochene Zusagen können Frust und Spannung erzeugen.',
                expectationA=f'A erwägt bei {title}: „B möchte, dass ich Verantwortung übernehme“ oder „B könnte übersehen, dass ich gerade etwas anderes erledigen muss“.',
                expectationB=f'B erwägt: „A versucht {title} zuverlässig zu übernehmen“ oder „A braucht eine kleinere Teilaufgabe, Hilfe oder mehr Zeit“.',
                metabelief='A kann vermuten, dass B A für zuverlässig oder überfordert hält. Diese Vermutung stammt aus eigenen beobachteten Rückmeldungen und ist keine Tatsache über B.',
                witnesses='Ein anwesendes Kind hört nur den ausgesprochenen Auftrag; ein anderer Hausbewohner sieht nur sichtbare Erledigung. Private Begründungen bleiben privat.',
                w100=skill+' bei unsicherem Arbeitsschritt; Routine ohne relevante Unsicherheit ohne Probe. Kooperation benötigt zusätzlich freiwillige Zusage.',
                pair=None, positive='Gemeinsam eine machbare Teilaufgabe vereinbaren, Hilfe anerkennen und tatsächlich erledigte Arbeit fair würdigen.',
                conflict='Eine zugesagte Aufgabe bleibt offen; jemand deutet das vorschnell als Gleichgültigkeit. Rückfrage und neue Zuständigkeit sind der positive Gegenweg.'))

# Paired situations are individually authored below. Each pair yields a conflict
# and an independently possible constructive interaction, linked by stable IDs.
def paired(catalog, prefix, groups):
    count=0
    for context, age, skill, source in groups:
        for line in source.strip().splitlines():
            title, conflict, constructive, trigger, settlement, effect, expects = line.split('|')
            expect_a, expect_b=expects.split(' / ')
            ids=[f'{prefix}{count*2+1:03}',f'{prefix}{count*2+2:03}']
            for n in range(2):
                ROWS.append(dict(id=ids[n], catalog=catalog,
                    title=title+(' · Konflikt' if n==0 else ' · Kooperation'), context=context,
                    age=age, tone='Konflikt' if n==0 else 'Positive Interaktion',
                    description=(conflict if n==0 else constructive)+'. '+('Eine faire Klärung bleibt möglich: '+settlement+'.' if n==0 else 'Wenn Zeit, Grenzen oder Ressourcen dagegenstehen, ist Vertagen oder eine klare Ablehnung ein gültiger Ausgang.'),
                    trigger=trigger+'; beide Beteiligten kennen mindestens den ausgesprochenen Anlass und sind über einen tatsächlichen Kontakt erreichbar.',
                    resolution=settlement+'. Möglich sind Zustimmung, ein Gegenangebot, ein Teilkompromiss, freiwilliges Vertagen oder ein respektiertes Nein.',
                    effects=effect+'. Beziehungseffekte bleiben richtungsabhängig; vollendete Handlungen und persönliche Deutungen werden getrennt protokolliert.',
                    expectationA='A: '+expect_a+'. Alternativ kann B einen anderen, noch unbekannten Grund haben.',
                    expectationB='B: '+expect_b+'. Die eigene Belastung und bekannte Vorgeschichte verschieben diese Erwartung.',
                    metabelief='A fragt sich, ob B A als '+('unzuverlässig, fordernd oder wenig verständnisvoll' if n==0 else 'hilfsbereit, verlässlich oder offen für eigene Bedürfnisse')+' wahrnimmt. Nachfragen kann diese Vermutung bestätigen oder korrigieren.',
                    witnesses='Bei Dritten wägen beide öffentliche Anerkennung, Beschämung und Diskretion ab. Beobachtende erhalten nur hörbare Aussagen und sichtbare Schritte; ein vertraulicher Teil kann an einen ruhigeren Ort verlegt werden.',
                    w100=skill+' bewertet die konkrete Ausführung oder Verständlichkeit; eigene Bereitschaft, Grenzen und Ressourcen entscheiden zusätzlich über Annahme.',
                    pair=ids[1-n], positive=constructive+'.', conflict=conflict+'.'))
            count+=1
    assert count==50,(catalog,count)

