def expectations():
    for i,line in enumerate(EXPECTATIONS.strip().splitlines()):
        title,context,cue,main,alternative,clarification=line.split('|')
        for n,belief in enumerate((main,alternative)):
            ROWS.append(dict(id=f'F{i*2+n+1:03}',catalog='expectations',title=title+(' · Hypothese 1' if n==0 else ' · Gegenhypothese'),context=context,
                age='14–17, ≤1 Jahr Abstand, strikt harmlos' if context=='Jugendromantik' else 'ausschließlich Erwachsene' if 'Romantik' in context or 'Partnerschaft' in context else 'altersgerecht zur konkreten Kontaktrolle',
                tone='Unsichere Erwartung',description=f'B beobachtet: {cue}. B erwägt: „{belief}“.',
                trigger='Die eigene Wahrnehmung muss mit Ort, Zeitpunkt, Sinneskanal und tatsächlicher Quelle vorliegen; kein Zugriff auf Aʼs private Motive.',
                resolution=clarification+'. Ohne neue eigene Evidenz bleibt die Annahme unsicher und zerfällt mit der Zeit.',
                effects='Die Hypothese kann Neugier, Hoffnung, Unsicherheit, Frust oder Rückzug beeinflussen. Eine widerlegte Annahme verändert Zuversicht und Interpretation, aber nicht das tatsächlich beobachtete Ereignis.',
                expectationA='A könnte vermuten, B werde '+('Kritik, eine Verpflichtung oder einen Näheanspruch' if n==0 else 'Hilfe, sachliche Information oder freiwilligen Kontakt')+' erwarten; A kann deshalb seinen tatsächlichen Anlass ausdrücklich benennen.',
                expectationB='B: '+belief+'. Gleichzeitige Alternative: '+(alternative if n==0 else main)+'.',
                metabelief='B vermutet zusätzlich: „A glaubt vielleicht, dass ich '+('Zustimmung, Kritik oder eine persönliche Bitte' if n==0 else 'einen offenen sachlichen Austausch')+' erwarte“. Tiefe 2 ist begrenzt und wird nicht als Wissen über A gespeichert.',
                witnesses='Eine dritte Person hat ihre eigene Sicht und kennt nur direkt wahrnehmbare Teile ab ihrer Ankunft. Bekanntschaft überträgt keine privaten Motive oder vollständigen Gespräche.',
                w100='Wahrnehmung/Empathie bewertet die Qualität einer ausdrücklich gewählten Beobachtung oder Rückfrage; auch ein hoher Erfolg liefert keinen Zugriff auf private Gedanken.',
                pair=f'F{i*2+(2 if n==0 else 1):03}',positive='Offen nach Anlass fragen, eigenes Bedürfnis nennen und eine freie Antwort respektieren.',conflict='Die erste Deutung als sicheren Vorwurf aussprechen und widersprechende Evidenz ignorieren.',
                prior_example={'hypothesis': .45 if n==0 else .30, 'alternative': .30 if n==0 else .45, 'unknown': .25, 'status':'illustrative, uncalibrated'}))
    assert i==49,i

OVERVIEW = r'''
<header><p class="kicker">VIVARIUM · LIVING WORLD · ENTWURF ZUR BESPRECHUNG</p><h1>Menschen, Erwartungen<br>und ein lebendiger Alltag</h1><p class="lead">Ein prozedurales, heuristisches und probabilistisches Theory-of-Mind-System mit nachvollziehbaren W100-Proben, eigenem Gedächtnis für jeden Sim und konsistenten Übergängen zum Storyteller.</p><div class="badges"><span>600 dokumentierte Beispiele</span><span>6 Kataloge × 100</span><span>Fakten ≠ Vermutungen</span><span>Stand: 6. Oktober 2026</span></div></header>
<nav><a href="#overview">Überblick</a><a href="#ages">Bedürfnisse & Altersgrenzen</a><a href="#tom">Theory of Mind</a><a href="#w100">W100</a><a href="#integration">Einbauplan</a><a href="#catalog">Tabellenanhang</a><a href="#sources">Quellen</a></nav>
<section id="overview"><h2>Was sich ändern soll</h2><p>Eine Begegnung soll einen konkreten Anlass und mehrere plausible Deutungen haben. Ein Kind kann nach der Schule zugleich auf einen Ausflug hoffen und eine Ermahnung befürchten. Ein Kollege kann eine Frage seines Chefs als neue Arbeit, Feedback oder Anerkennung verstehen. Ein angesprochener Erwachsener kann Flirt vermuten, ohne eine Auskunft oder höflichen Kontakt auszuschließen. Andere Sims im Raum verändern Diskretion, Gesprächsform und mögliche Zeugen; ihre privaten Gedanken werden dadurch nicht sichtbar.</p><p>Das Ziel sind <strong>eigenständige, unvollständig informierte Personen</strong>: jeder Sim hat Wünsche, konkrete Verpflichtungen, Fähigkeiten, Ressourcen, bekannte Beziehungen, aktuelle Gefühle und eine subjektive Geschichte. Kooperation, Grenzen, Missverständnisse und Reparaturen sollen ebenso häufig möglich sein wie Konflikte. Eine Nachbarschaft darf freundlich, widersprüchlich und gelegentlich überraschend sein, ohne aus zufälligen Skandalen zu bestehen.</p><div class="callout"><b>Umfang dieses Dokuments.</b> Der große neue Interaktions- und ToM-Katalog ist ein Implementationsvorschlag. Er ist noch kein aktivierter Simulationskatalog. Bereits umgesetzt werden die separat angefragten Biografie-Fehlerkorrekturen, Mind-Navigation, Beziehungsbeschriftungen und die Aufteilung der Kontaktbedürfnisse samt Altersregeln. Die Tabellen sind bewusst umfangreich; nicht jede Zeile braucht später ein eigenes Spezialmodul.</div>
<div class="grid"><article><h3>Anlass</h3><p>Warum sprechen die Sims gerade? Eine offene Aufgabe, eine tatsächliche Beobachtung, freie Freizeit, ein Wunsch nach Kontakt oder ein konkretes Angebot.</p></article><article><h3>Eigene Sicht</h3><p>Was weiß A tatsächlich? Was vermutet A über B? Was glaubt A, wie B A einschätzt? Für B gilt dieselbe Trennung.</p></article><article><h3>Entscheidung</h3><p>A kann fragen, helfen, abwarten, ablehnen, ein Gegenangebot machen oder eine eigene sichere Tätigkeit wählen.</p></article><article><h3>Folge</h3><p>Nur tatsächlich bestätigte Handlungen ändern Fakten. Gedanken, Vertrauen und Erwartungen ändern sich aus eigenen Beobachtungen.</p></article></div>
<h3>Keine eintönigen Gedanken</h3><p>Ein Gedanke erhält mehrere Slots: <code>eigener Wunsch → konkrete Beobachtung → mögliche Absicht → Unsicherheit → nächster kleiner Schritt</code>. Beispiele: „Ich möchte noch spielen. Papa schaut zum Schreibtisch; vielleicht erinnert er an die Hausaufgaben, vielleicht interessiert ihn mein Modell. Ich frage erst, was er meint.“ Oder: „Die neue Projektfrage macht mich nervös. Nach der letzten guten Rückmeldung könnte es Anerkennung sein; heute habe ich allerdings schon viel Arbeit. Ich möchte den Anlass wissen, bevor ich etwas zusage.“</p><p>Jeder Gedanke braucht einen aktuellen Auslöser oder ein relevantes persönliches Ereignis. Ein Thema bleibt über mehrere passende Schritte bestehen; neue Sätze wechseln nicht zufällig die gesamte Persönlichkeit. Ein Wiederholungsverlauf speichert letzte Themen, Formulierungsfamilien und tatsächlich gemachte Erfahrungen. Varianten stammen aus Kontext, Perspektive und Verlauf, nicht nur aus Synonymen. Für Kinder unter 3 werden einfache Bedürfnisse und Bindungserwartungen beschrieben, keine ausformulierten erwachsenen Verhandlungen.</p></section>

<section id="ages"><h2>Zwei getrennte Kontaktbedürfnisse</h2><div class="tablewrap"><table><thead><tr><th>Dimension / Alter</th><th>Werte und Bedeutung</th><th>Zulässige Wirkung</th><th>Harte Grenze</th></tr></thead><tbody>
<tr><td>Soziale Wärme · alle</td><td><code>needs.social</code>, 0–1; 0 = gut versorgt, hoher Wert = unerfülltes Bedürfnis.</td><td>Freundschaft, Zugehörigkeit, Trost, Familiennähe, gemeinsames Spielen, Hilfe und Gespräch.</td><td>Freundlicher Kontakt ist kein Beweis romantischer Absicht und keine automatische romantische Bedürfnisbefriedigung.</td></tr>
<tr><td>Romantische Zuneigung · unter 14</td><td><code>needs.romantic_affection = 0</code>, immer.</td><td>Keine Romantik; familiäre und freundschaftliche Wärme bleibt möglich.</td><td>Kein romantischer, erotischer oder sexueller Interaktionspfad.</td></tr>
<tr><td>Romantische Zuneigung · 14–17</td><td>0–0,35; moderate unerfüllte Sehnsucht nach harmloser jugendlicher Zuneigung.</td><td>Nur seichtes Schwärmen, romantische Gespräche und harmlose öffentliche Dates zwischen zwei 14–17-Jährigen mit <strong>höchstens einem Jahr Altersunterschied</strong>.</td><td><strong>Niemals sexuelle Interaktionen, erotische Darstellung, Sexualisierung oder Begehren bei Minderjährigen.</strong> Kein Erwachsenen/Minderjährigen-Romantikpfad. Keine verwandten romantischen Beteiligten.</td></tr>
<tr><td>Romantische Zuneigung · Erwachsene</td><td>0–1; ab 0,65 kann erwachsenes Begehren gewichtet werden; ab 0,75 ein privater Intimitätswunsch.</td><td>Freiwillige Annäherung, erwachsene Dates, Bindung, erwachsenes Begehren; Eifersucht als eigene unsichere Reaktion.</td><td>Bedürfnisintensität ersetzt keine Zustimmung. Private Intimität nur zwei nicht verwandte Erwachsene 18+, eigene freiwillige Bereitschaft, geeigneter privater Raum ohne weitere Anwesende; nicht explizite Darstellung.</td></tr>
</tbody></table></div><p>Die Schwellen sind explizite Spielparameter, keine psychologischen Messwerte. Ein hoher Wert beschreibt einen Wunsch, nicht einen Anspruch an andere. Ein „Nein“ wird nicht durch hohe Werte, Charisma oder W100-Erfolg aufgehoben. Jugendromantik verwendet getrennte Kategorien <code>teen_romantic_talk</code> und <code>teen_date</code>; sie greift nie auf erwachsene Sexualitätskategorien zurück.</p><p>Bestehendes <code>social</code> bleibt erhalten und heißt in der UI „Soziale Wärme“. Die neue Dimension wird reproduzierbar und altersbegrenzt initialisiert; vorhandene Beziehungen, Ereignisse und tatsächliche Erfolge bleiben erhalten. UI, Stats-API, Modellreflexion, Tick, Migration, Import und Replay brauchen dieselben Werte- und Interaktionsgrenzen. Das aktuelle Regelmodul setzt die Caps und trennt die Jugendkategorien; der weitere Entwurf erweitert anschließend Inhalte und Zustandsautomaten.</p><p><strong>Textschutz:</strong> Die Altersgrenze wird zuerst bei strukturierten Kandidaten und Ereignissen geprüft. Modellprompts erhalten dieselbe Regel; ein zusätzlicher Filter verwirft eindeutig sexualisierte Antworten in Minderjährigenkontexten vor Speicherung. Für die spätere belastbare Erweiterung bleiben Minderjährigen-Aktionen auf zugelassene strukturierte Klassen beschränkt; freie Modellprosa darf keine physische Handlung ergänzen. Ein Wortfilter allein ist keine semantische Vollprüfung beliebiger Sprache.</p></section>

<section id="tom"><h2>Ein begrenztes subjektives Modell von anderen</h2><div class="flow"><span>Eigene Wahrnehmung</span><b>→</b><span>2–5 Hypothesen + unbekannt</span><b>→</b><span>gewichtete Erwartung</span><b>→</b><span>eigene Entscheidung</span><b>→</b><span>neue Evidenz</span></div>
<h3>Vier getrennte Ebenen</h3><ol><li><strong>Fakt:</strong> A sagt B am tatsächlichen Ort: „Kannst du nachher kurz kommen?“ Ort, Zeit, Teilnehmer und hörbare Worte sind ein Ereignis.</li><li><strong>Wahrnehmung:</strong> B hört den Satz. C betritt den Raum später und hört ihn nicht. Entfernung, Aufmerksamkeit, geschlossene Tür, Privatsphäre und Sinneskanal entscheiden, was jeweils beobachtet wird.</li><li><strong>Inference:</strong> B hält Zusatzarbeit für möglich, daneben Anerkennung oder einen privaten Anlass. Quellen, Wahrscheinlichkeit, Alternative und Ablaufzeit bleiben gespeichert.</li><li><strong>Metabelief:</strong> B vermutet, A rechne mit seiner Zustimmung. Das ist eine begrenzte zweite Ebene <code>B glaubt, A glaubt …</code> und kein Blick in Aʼs Kopf.</li></ol>
<p>Die tatsächliche Absicht von A bleibt in Aʼs eigener Entscheidung. B darf sie erst nach einem beobachteten Informationsweg besser kennen. Gleiche Verwandtschaft, derselbe Raum, ein Anker oder ein Relationship-Graph erlauben keinen Zugriff auf fremde Gedanken. Direkte Aussagen sind zunächst <em>Claims</em>; B kann sie ernst nehmen, ohne sie automatisch als überprüfte Welttatsache einzutragen.</p>
<h3>Hypothesen und Aktualisierung</h3><p>Pro aktuellem Thema werden höchstens vier konkrete Absichten plus <code>unknown/other</code> gehalten: etwa Hilfe anbieten, Hilfe erbitten, Aufgabe verteilen, Kontakt suchen, kritisieren, Anerkennung geben, Grenze setzen oder harmlosen/erwachsenen Flirt anbieten. Kontext und bekannte Rolle bestimmen zulässige Kandidaten; Geschlecht, Hautfarbe oder „hübsch“ liefern <strong>keine feste Absichtsregel</strong>. Unterschiedliches Alter verändert passende Sprache, Verantwortungen und Interessen, nicht automatisch Intelligenz oder gute Absicht.</p><pre>score(h) = log(prior(h | bekannte Rolle, Situation))
         + beobachtete Hinweise · Evidenzgewichte
         + eigene Unsicherheit / Stimmung / gelernte Erwartungen
P(h) = softmax(score(h) / Temperatur), danach normalisieren
P_neu(h) ∝ P_alt(h) · Likelihood(neue eigene Beobachtung | h)
P_veraltet = (1 − λ) · P_alt + λ · breiter Kontextprior</pre><p>Alle Merkmale müssen aus der eigenen erlaubten Perspektive stammen. Vertrauen verbessert die Gewichtung früherer <em>selbst beobachteter</em> Zusagen; es wird kein Zugriff auf Bʼs tatsächlich verborgene nächste Absicht. Stress erhöht Unsicherheit oder negative Deutungen begrenzt, Neugier erhöht Rückfragen, Gewissenhaftigkeit erhöht Planbedarf, Kontaktfreude erhöht aktive Kontaktangebote. Temperatur und Gewichte sind kleine editierbare Spielparameter. Unklare Beobachtung erhält eine breite Verteilung und einen echten Unbekannt-Anteil; Konfliktneigung darf nicht aus einem einzigen Ereignis eine sichere Feindschaft machen.</p>
<div class="simulator"><h3>Interaktives Beispiel: „Komm bitte kurz vorbei“</h3><p>Dies sind illustrative Spielgewichte, keine empirisch kalibrierten menschlichen Wahrscheinlichkeiten. Die verdeckte wirkliche Absicht wird zur Berechnung nicht gelesen.</p><label>Eigener Stress <input id="stress" type="range" min="0" max="100" value="30"></label><label>Eigene bisherige Verlässlichkeitserfahrung <input id="rapport" type="range" min="0" max="100" value="60"></label><label>Beobachteter Zusatzhinweis <select id="evidence"><option value="none">keine weiteren Informationen</option><option value="agenda">A sagt: „Es geht um ein neues Projekt“</option><option value="praise">A nennt meine tatsächlich gute Leistung</option><option value="boundary">A sagt: „Du kannst auch morgen antworten“</option></select></label><div id="probabilities"></div><p id="thought-demo"></p></div>
<h3>Gedächtnis, Erwartungen und positive Gegenwege</h3><p>Jeder Eintrag enthält <code>observer_id, subject_id, topic, hypothesis, probability, evidence_ids, modality, updated_at, expires_at, certainty_label</code>. Zweite Ebene zusätzlich <code>about_self</code>. Festgehalten wird auch, welche Aussage sich später bestätigte oder nicht; weder Erwartung noch Enttäuschung schreibt alte Fakten um. Selbst wahrgenommene Erfahrungen verändern eine situationsbezogene Erwartung, nicht pauschal „alle Erwachsenen“, „alle Frauen“ oder „alle Senioren“.</p><p>Im Mind-Fenster erscheinen „Ich wünsche mir“, „Ich vermute“, „Andere könnten von mir erwarten“ und „Woran ich das festmache“. Ein Klick auf eine Quelle zeigt den eigenen Journalbeleg. Prozentwerte können optional technisch eingeblendet werden; normale Gedanken verwenden „vielleicht“, „wahrscheinlich“ oder „ich weiß es noch nicht“. Profile und Beziehungsgraph zeigen beobachtete Rollen und gemeinsame Geschichte; ToM bleibt ausdrücklich die Sicht des ausgewählten Sims.</p>
<h3>Dritte, Publikum und Gesprächsgruppen</h3><p>Eine Begegnung besitzt eine Teilnehmergruppe, momentane Anwesende und eine separate Zeugenliste. Diskretion, öffentliche Anerkennung, Beschämungsrisiko, Loyalität und gemeinsame Gruppenziele beeinflussen die Wahl. Ein Dritter darf ein Missverständnis durch eine <em>tatsächlich ausgesprochene</em> Information auflösen, vermitteln, eine Grenze setzen oder eine eigene Aktivität fortsetzen. Nicht jeder im Raum hört jedes Wort; Telefonate sind nur für die nachweisbaren Gesprächspartner vollständig bekannt. Private erwachsene Nähe ist bei weiteren Anwesenden ausgeschlossen.</p><p>Bei großen Festen werden nur kleine erreichbare Gesprächscluster verarbeitet. Zuschauer sehen einen begrenzten relevanten Ausschnitt statt jedes vollständigen Dialogs. Gemeinsames Wissen wird nur angenommen, wenn alle Beteiligten einen bestätigten Informationsweg teilen; ein räumlicher Nachbar ohne Hörzugang weiß es nicht.</p></section>

<section id="w100"><h2>W100: Können, Schwierigkeit und echte Freiwilligkeit</h2><p>Open Sims enthält bereits <code>living_world/percentile.py</code> mit sieben Attributen, sozialen Fertigkeiten und reproduzierbaren W100-Ergebnissen. Der heutige Vivarium-Python-Adapter bindet <code>psychology, careers, affect</code> an, aber noch nicht den vollständigen W100-Ausführungspfad. Deshalb soll die Erweiterung dieses Modul explizit anbinden, statt nur eine fiktive gewürfelte Zahl im Text zu nennen.</p><div class="tablewrap"><table><thead><tr><th>Prüfung</th><th>Frage</th><th>Beispiel</th><th>Was sie nicht entscheidet</th></tr></thead><tbody><tr><td>Objekt / Pflicht</td><td>Wie gut gelingt ein unsicherer konkreter Schritt?</td><td>Koordination beim sicheren Reparieren, Denken bei Planung, Wahrnehmung bei Kochen.</td><td>Keine erfundenen Werkzeuge, Wege, Besitzrechte oder erledigte Arbeit ohne reale Ausführung.</td></tr><tr><td>Soziale Ausführung</td><td>Wie klar, empathisch oder überzeugend ist das Angebot?</td><td>Empathie + Präsenz für Trost, Überzeugen + Denken für Gründe.</td><td>Keine automatisch erzeugte Zustimmung, Liebe, Vergebung oder Preisgabe privater Daten.</td></tr><tr><td>Perspektivenfrage</td><td>Wie gut formuliert A eine offene Rückfrage oder bemerkt eine sichtbare Irritation?</td><td>Wahrnehmung oder Empathie mit begrenztem Kontextmodifier.</td><td>Kein Wahrheitswürfel und kein Zugriff auf private Gedanken.</td></tr><tr><td>Arbeit / Kunst</td><td>Wie gut gelingt die tatsächlich ausführbare Aufgabe?</td><td>Fachspezifische Fertigkeit plus passendes Attribut.</td><td>Kein Jobstatus oder Karriereschritt ohne zuständige reale Entscheidung.</td></tr></tbody></table></div>
<pre>Schwelle = clamp(0,65 × Fertigkeit + 0,35 × Attribut + 9
                 − Bedürfnisdruck − Schwierigkeit, 5, 95)
Wurf = reproduzierbarer Integer 1 … 100
excellent: Wurf ≤ max(1, floor(Schwelle / 5))
success:   Wurf ≤ Schwelle
setback:   Wurf ≥ 100 − max(1, floor((100 − Schwelle) / 6))
mixed:     sonst — gemischter Verlauf / Ziel nicht vollständig erreicht</pre><p>Diese Formel und Grade entsprechen dem vorhandenen Modul. Bedürfnisdruck berücksichtigt aktuell Müdigkeit, Hunger und Durst; Schwierigkeit ist begrenzt. Neue Kontextmodifier müssen versioniert und auditiert werden, etwa schlechte Sicht, knappe Zeit oder fehlende Privatsphäre. Private Motive des Gegenübers dürfen nicht heimlich in die Schwelle einfließen. Romantische Intensität kann die Wahl eines zulässigen Angebots beeinflussen, ist aber kein Fertigkeitsbonus, der Grenzen überwindet.</p>
<div class="simulator"><h3>W100-Rechner nach der vorhandenen Formel</h3><div class="calculator"><label>Fertigkeit <input id="skill" type="number" min="1" max="99" value="60"></label><label>Attribut <input id="attribute" type="number" min="1" max="99" value="55"></label><label>Bedürfnisdruck <input id="pressure" type="number" min="0" max="28" value="5"></label><label>Schwierigkeit <input id="difficulty" type="number" min="-25" max="30" value="8"></label><label>W100-Wurf <input id="roll" type="number" min="1" max="100" value="42"></label></div><p id="roll-result"></p></div>
<p><strong>Zwei Entscheidungen statt „Charisma erzwingt Ja“:</strong> Zuerst gelten Alters-, Verwandtschafts-, Zugangs- und Kontaktgrenzen. Bei einer zulässigen Interaktion prüfen beide Sims die eigene Bereitschaft aus eigenen Wünschen, aktueller Kapazität, eigenen Zusagen und bekannten Optionen. Nur für die tatsächliche unsichere Ausführung wird anschließend eine W100-Probe protokolliert. Ein gelungenes Angebot kann verständlicher sein; B kann es trotzdem frei ablehnen oder ein Gegenangebot machen. Kein weiterer Wurf nach einem klaren Nein ohne neue freiwillige Öffnung.</p><p>Routine ohne bedeutsame Unsicherheit braucht keine Probe. Für längere Aufgaben wird am sinnvollen Abschluss oder einem relevanten Meilenstein genau einmal gewürfelt, nicht jede Minute. Ein Fehlversuch verändert nur begründete Folgen: mehr Zeit, Bitte um Hilfe, geringe Qualität oder ein kleiner Reparaturschritt; keine unverhältnismäßige Katastrophe beim alltäglichen Aufräumen. Der gespeicherte Wurf wird bei Storyteller-Übernahme und Replay wiederverwendet.</p></section>

<section id="integration"><h2>Wie das in das bestehende Vivarium eingebaut wird</h2><h3>Gegenwärtiger Ausgangspunkt</h3><p><code>server/living/engine.js</code> koordiniert Wege, Aktionen, Anwesenheit, Ankerfelder, Modellvorschläge und atomaren Commit. <code>cognition.js</code> verbindet Gefühle, Bedürfnisse und tatsächlichen Zielprogress. <code>social.js</code> liefert soziale Ausgangskontakte und Texte. <code>open_sims_worker.py</code> nutzt vorhandene Kandidaten und eigene beobachtete Erinnerungen; der aktuelle ToM-Bestand ist hauptsächlich ein kleiner Empfangs-/Verfügbarkeitsindikator aus akzeptierten oder abgelehnten Kontakten. <code>vivarium.js</code> bindet Bühne, ruhige Gespräche und Gedankenansicht ein.</p><div class="tablewrap"><table><thead><tr><th>Neues Modul / Erweiterung</th><th>Aufgabe</th><th>Bestehender Einbaupunkt</th><th>Prüfbare Ausgabe</th></tr></thead><tbody>
<tr><td><code>interaction_catalog</code></td><td>Versionierte Definitionen: Rollen, Alter, Zugang, Kontext, Auslöser, Ressourcen, Motive, Ausgänge, Gegenwege.</td><td>Katalog-/Kandidatenpfad im Python-Adapter; redaktionelle JSON-Daten aus diesem Anhang.</td><td>Stabile IDs, keine ungeprüften beliebigen Kategorien.</td></tr>
<tr><td><code>obligations</code></td><td>Aufgaben mit Ursprung, Zuständigkeit, Frist, Aufwand, Ressourcen und tatsächlichem Erledigungsstand.</td><td>Vor der bisherigen Auswahl von <code>scheduledDestination</code> und lokalen Aktionen.</td><td>Ein Plan ist keine erledigte Aufgabe; Zusage und Abschluss bleiben getrennt.</td></tr>
<tr><td><code>perception</code></td><td>Eigener Blick-/Hörzugang, Gesprächsrollen, Privatsphäre, Eintrittszeit und anwesende Dritte.</td><td>Aktuelle Anwesenheits-Samples und Ereignis-/Zeugenaufbau.</td><td>Jeder Journalbeleg hat einen erlaubten Informationsweg.</td></tr>
<tr><td><code>tom</code></td><td>Hypothesen, Posterior, Unsicherheit, Verfall und begrenzte zweite Ebene aus eigener Evidenz.</td><td>Nach Wahrnehmung, vor sozialer Kandidatenwahl; nochmals nach akzeptiertem Ergebnis.</td><td>Kein Lesen von <code>other.state.thought</code> oder geheimen Zielen.</td></tr>
<tr><td><code>interaction_sessions</code></td><td>Mehrschrittige Angebote, Antworten, Gegenangebote, Pausen und Reparaturen.</td><td>Ersetzt die rein sofortige Abwicklung relevanter sozialer Ereignisse.</td><td>Ein Sim führt höchstens eine aktive kompatible Sitzung, mit Deadline und Konfliktprüfung.</td></tr>
<tr><td><code>percentile</code></td><td>Vorhandenes W100-Modul anbinden, Inputs und Ergebnis speichern.</td><td>Neue reine Adapter-Operation; vor endgültiger Anwendung unsicherer Schrittfolgen.</td><td>Ein Wurf je Versuch, kein Neuwürfeln im Modell, gleiche Wiederherstellung.</td></tr>
<tr><td><code>thought_templates</code></td><td>Konkrete mehrteilige Perspektiven aus Wunsch, Evidenz und Unsicherheit.</td><td><code>proceduralThought</code> und prozedurale Ereignisbeschreibung.</td><td>Geprüfte altersgerechte Varianten ohne erfundene Tatsachen.</td></tr>
<tr><td><code>story_context</code></td><td>Eigene Erwartungen, tatsächliche Kontakte, Aufgaben und bereits gewürfelte Folgen pro erzähltem Sim.</td><td><code>mindContext</code>, <code>personalSocialContext</code>, ruhige Gespräche und Storyteller-Batches.</td><td>Modell kann innere Deutung verfeinern; physische Handlung, Zustimmung und Altersgrenze bleiben validiert.</td></tr>
<tr><td>Mind / Profile / Bonds</td><td>Absichten, Hypothesen, Quellen, aktuelle Zusagen, Kontaktgrenzen und Rollen sichtbar machen.</td><td>Vorhandene Mind-Aktionsleiste, Stats & Protokoll und persönlicher Graph.</td><td>Perspektive explizit auswählbar; Fokuswechsel verändert keine Weltzeit.</td></tr>
</tbody></table></div>
<h3>Tick-Reihenfolge und Übergang zum Anker</h3><ol><li>Weltversion, Regeln und Startzustand lesen; relevante fällige Aufgaben und tatsächliche Erreichbarkeit bestimmen.</li><li>Bedürfnisse seit der letzten Änderung fortschreiben und Alters-Caps anwenden. Eigene Ziele, Verpflichtungen und Erwartungen erzeugen begrenzte zulässige Kandidaten.</li><li>Nicht verankerte Sims planen zuerst tatsächliche Wege, Objektaktionen und soziale Angebote. Anwesenheit und Informationswege werden entlang des Ticks gesammelt, nicht nur am Endpunkt.</li><li>Bei tatsächlichem Kontakt mit einem Sim-Anker oder Aufenthalt in einem Ortsanker entsteht ein Erzählfeld. Laufende Sitzung, eigene Erwartung, aktuelle Arbeit und letzter tatsächlicher Stand werden übergeben.</li><li>Der Storyteller erhält getrennt <code>facts</code>, <code>own_observations</code>, <code>own_hypotheses</code>, <code>commitments</code>, <code>rolls</code> und <code>allowed_outcomes</code>. Er darf emotionale Nuancen, plausible Motive und vorgeschlagene nächste Schritte formulieren; er bekommt keine Befugnis zu Teleportation, erzwungener Zustimmung oder neu erfundenen früheren Ereignissen.</li><li>Revisionen ändern nur zulässige provisorische soziale Deutungen/Kategorien am selben Ort/Zeitpunkt mit denselben Beteiligten. Vorher dokumentierte oder physisch abgeschlossene Fakten und Würfe bleiben bestehen.</li><li>Nach Prüfung werden Ereignisse, richtungsabhängige Wahrnehmungen, Hypothesenupdates, Bedürfnisfolgen und tatsächliche Aufgabenstände zusammen atomar gespeichert. Abbruch oder ungültige Modellantwort lässt die bisherige Version bestehen.</li></ol>
<p>Bei einem neu gesetzten Anker werden die letzten relevanten <em>eigenen</em> Quellen, offene Zusagen und aktuelle Hypothesen aufgenommen. Ein prozeduraler Text wie „Fiona sitzt am Schreibtisch und beginnt die bekannte Aufgabe“ bleibt ein echtes beschriebenes Ereignis auch ohne passende Sitzgrafik. Der Storyteller darf daraus heutige Gefühle ableiten, aber keine früher nicht modellierten Details nachträglich als beobachtet eintragen.</p>
<h3>Datenmodell und Skalierung</h3><pre>interaction_session {id, rule_version, catalog_id, participants, location,
  phase, proposal, responses, consent, witnesses, deadline, roll_ids}
obligation {id, issuer, assignee, source_event, due_at, status,
  estimated_duration, resources, accepted_at, completion_event}
tom_hypothesis {observer, subject, topic, depth: 1|2, hypothesis,
  probability, evidence_ids, modality, updated_at, expires_at}
percentile_check {id, attempt_id, rule_version, seed_key, task,
  skill, attribute, pressure, difficulty, threshold, roll, grade}</pre><p>Bestehende <code>lw_events/lw_journal/lw_relations</code> bleiben kanonisch. Neue indexierte Tabellen speichern aktive Sitzungen, Aufgaben und kompaktes aktuelles ToM; unveränderliche Ereignisse speichern den Auditverlauf. Kleine Versionen können die begrenzten aktuellen Hypothesen zunächst im Sim-State halten, benötigen aber eine klare Größenbegrenzung. ZIP-Export, Import-ID-Remapping, Duplikation und Replay müssen die neuen Tabellen samt Evidenz- und Würfelverweisen übernehmen.</p><p>Vorschlag pro Sim: höchstens 24 aktive Kontaktmodelle, je drei aktuelle Themen, je vier Hypothesen plus unbekannt; zweite Ebene nur für ein besonders relevantes Thema. Höchstens acht aktive lokale Gesprächskandidaten und zwölf aktive Aufgaben im Hot-State; weitere bestätigte Termine liegen indiziert auf Platte. Ereignisse und persönliche Geschichte werden nicht abgeschnitten, sondern als kalte Historie gehalten. TTL und LRU betreffen aktuelle Hypothesen, nicht das tatsächliche autobiografische Protokoll.</p><p>Keine Welt- oder Raum-All-to-all-Paare. Räumlicher Index und kleine Gesprächscluster begrenzen Begegnungen; eine Priority Queue aktiviert fällige Sims/Sitzungen/Tasks. Bedarf und Hypothesenzerfall werden analytisch fortgeschrieben. Die heutige Minute-für-Minute-Iteration ist für Millionenstädte zu ersetzen; 500 funktionierende Sims sind kein Nachweis für eine Millionenstadt. Bilder und Minimap bleiben im bestehenden 50-Thumbnail-Budget unabhängig von der Textsimulation.</p>
<h3>Wiederholungsbremsen und emotional interessante Verläufe</h3><p>Jede Interaktionsfamilie hat eine echte Cooldownzeit, einen Kontextfilter und ein Wiederholungsgewicht. Zwei Freunde sollten nicht alle fünf Minuten denselben Smalltalk führen. Offene Hilfe, neues Wissen, tatsächliche Zielschritte und unerledigte Absprachen erzeugen Fortsetzungen. Konflikte brauchen konkrete Auslöser, nicht bloß einen Zufallswurf. Positive Erlebnisse erhalten ebenso Quellen, Folgeziele und spätere Bezugnahmen. Ein unerledigtes Versprechen, eine geglückte Lernhilfe oder ein ehrlich korrigiertes Missverständnis kann dadurch eine kleine mehrtägige Geschichte bilden.</p>
<h3>Einführung in fünf überprüfbaren Schritten</h3><ol><li><strong>10–20 Sims:</strong> 20 Pflichten, 12 soziale Sitzungen, begrenzte Wahrnehmung und erste Hypothesen. Eigene Eltern, Peers und ein kleines Arbeitsnetz. Vergleiche tatsächliche Protokolle und beobachtete Anwesenheit.</li><li><strong>W100 und Aufgaben:</strong> konkrete Objektressourcen, bestätigte Zusagen, unveränderlicher Wurf und Teilergebnisse; keine rein kosmetischen Fertigkeitszahlen.</li><li><strong>Anker und Modellübergabe:</strong> laufende Sitzung und begrenzte eigene Sicht an den Storyteller; dieselbe Welt mit/ohne wechselnde Anker physisch konsistent halten.</li><li><strong>50–100 Sims:</strong> komplexere Gruppen, Öffentlichkeit, Beruf, Schule, Hobby und Familie; positive Reparaturen, unterschiedliche Tagespläne und Jugend-/Erwachsenen-Grenztests.</li><li><strong>500 Sims:</strong> CPU/RSS, DB-Wachstum, Kontextlänge, Warteschlangen, aktive Hypothesen und Wiederholungsrate messen. Vor größerer Stadt ereignisgesteuerte Verarbeitung und Partitionierung einführen.</li></ol>
<h3>Tests, die dieses Verhalten wirklich belegen</h3><ul><li>False-belief-Fall: A sieht eine Ortsänderung eines Gegenstands, B nicht. B handelt bis zu einer echten neuen Quelle aus seinem alten Wissen.</li><li>Dritte Person betritt später den Raum; sie kennt frühere private Sätze nicht. Eine geschlossene Tür oder ein privates Telefonat überträgt keine Motive.</li><li>Hilfeangebot, Absage und Gegenangebot ändern Erwartungen richtungsabhängig. Ein einzelnes Nein erzeugt keine dauernde Feindschaft.</li><li>Gleiche Ereignisse und Seeds liefern gleiche W100-Ergebnisse, Orte und objektive Geschichte. Modellformulierungen dürfen die Tatsachen nicht ändern.</li><li>Unter 14 bleibt romantische Zuneigung bei null; 14–17 nie über 0,35. Jugendromantik nur 14–17 mit Altersabstand ≤1. Alle sexuellen Kategorien und Erwachsenen/Minderjährigen-Romantik sind blockiert, auch bei Modellrevision, Import, Replay oder manipulierten Stats.</li><li>Ein hervorragender Überzeugungswurf kann auf Nein treffen. Keine Probe überschreibt Einwilligung, private Grenzen, Eigentum oder Altersregeln.</li><li>Mind und Szene stimmen über aktuelle Bedürfnisse, tatsächliche Tätigkeit, Gedankenquellen und bekannte Beziehung überein. Neu gesetzte Anker lesen vorhandene eigene Geschichte.</li><li>Pro simuliertem Tag: Anteil relevanter Interaktionen, Vielfalt der Motive, Wiederholungsrate, erfüllte/offene Zusagen, valide Zeugenbelege, Annahme-/Ablehnungsverteilung und Hypothesenkalibrierung aus eigenen belegten Rückfragen messen.</li></ul>
<p>Abnahmeziele: null verbotene Alterskombinationen, null private Wissenslecks, null unbelegte Erfolge, null doppelte Würfe pro Versuch. Qualitätsziele für Wiederholung und Verteilung erst aus dem 10–20-Sim-Pilot ableiten; keine willkürliche feste Konfliktquote erzwingen.</p></section>

<section id="catalog"><h2>Anhang: sechs detaillierte Kataloge</h2><p>100 Alltagsverpflichtungen; 50 Familien-/Generationssituationen mit je Konflikt und positivem Gegenweg; 50 Arbeits-/Schul-/Freizeitsituationen mit beiden Varianten; 50 erwachsene romantische Situationen mit beiden Varianten; 50 Verhandlungs-/Konfliktsituationen mit beiden Varianten; 50 mehrdeutige Situationen mit je zwei Erwartungshypothesen. Insgesamt <strong>600 Einträge</strong>. A und B bezeichnen konkrete Beteiligte, nicht feste Geschlechter oder unveränderliche Rollen.</p><p>Jede Tabellenzeile enthält Beschreibung, Auslöser, mögliche Auflösung, Folgen, beide Perspektiven, Metabelief, Dritte und W100. Ein Gegenweg ist eine neue freie Möglichkeit, kein garantiertes Happy End. Die Aufgabe Aʼs darf B nicht automatisch verpflichten. Jugendromantik steht getrennt in F055–F060 und unter den Altersregeln; Katalog D behandelt ausschließlich Erwachsene.</p><div class="filters"><label>Katalog <select id="category"><option value="all">Alle sechs Kataloge</option></select></label><label>Situation / Begriff <input id="search" placeholder="z. B. Hausaufgaben, Opa, Eifersucht, W100, Chef"></label><label>Art <select id="tone"><option value="all">Alle Arten</option><option>Konflikt</option><option>Positive Interaktion</option><option>Unsichere Erwartung</option><option>Pflicht mit positiver und Konfliktvariante</option></select></label><label>Zeilen <select id="page-size"><option>25</option><option>50</option><option>100</option></select></label><button id="export">Katalog als JSON sichern</button></div><div class="pager"><button id="prev">← Zurück</button><b id="results" aria-live="polite"></b><button id="next">Weiter →</button></div><p class="hint">Die Tabelle scrollt auf kleinen Bildschirmen horizontal. „Details“ zeigt zusätzliche Perspektiven, Dritte und Grenzen. IDs bleiben beim Filtern und Export stabil; Gegenwege sind anklickbar.</p><div class="tablewrap catalog"><table><thead><tr><th>ID / Situation</th><th>Beschreibung</th><th>Auslöser / Startbedingungen</th><th>Auflösung / Ausgänge</th><th>Erwartungen A & B</th><th>Antizipierte Effekte</th><th>W100 / Gegenweg</th></tr></thead><tbody id="rows"></tbody></table></div><noscript>Für die Suche und paginierten Tabellen JavaScript aktivieren. Der gesamte Katalog liegt zusätzlich in living-world-social-taxonomy.json.</noscript></section>

<section id="sources"><h2>Quellen und bewusste Entwurfsentscheidungen</h2><p>Die wissenschaftlichen Arbeiten liefern unterschiedliche Forschungsansätze für mentale Zustände und Verhaltenserwartungen. Dieser Vorschlag ist eine eigene begrenzte Spielheuristik, keine Implementierung oder Validierung eines wissenschaftlichen Menschenmodells.</p><ul><li><a href="https://proceedings.mlr.press/v80/rabinowitz18a.html">Rabinowitz et al., Machine Theory of Mind, ICML 2018</a>: Verhaltenserwartungen aus begrenzten Beobachtungen und Umgang mit falschen Überzeugungen motivieren die Trennung von Wissen und Vermutung. Hier wird kein neuronales ToMnet trainiert.</li><li><a href="https://www.nature.com/articles/s41562-017-0064">Baker et al., Rational quantitative attribution of beliefs, desires and percepts in human mentalizing, 2017</a>: Inspiration für inverse Planung und getrennte Hypothesen über Wahrnehmung, Wissen und Wunsch; die Gewichte im Spiel sind ausdrücklich unkalibriert.</li><li><a href="https://ojs.aaai.org/index.php/AAAI/article/view/4574">Shum et al., Theory of Minds: Understanding Behavior in Groups through Inverse Planning, AAAI 2019</a>: Inspiration für die Bedeutung von Gruppenbeziehungen. Die vorgeschlagenen begrenzten Gesprächscluster sind eine eigene technische Vereinfachung.</li><li>Lokaler Code: <code>vendor/open-sims/living_world/psychology.py</code> (Kandidaten, eigenes beobachtetes ToM), <code>percentile.py</code> (W100), <code>server/living/open_sims_worker.py</code>, <code>cognition.js</code>, <code>engine.js</code>, <code>romance.js</code>, <code>romance_policy.py</code> und <code>config/living_social_policy.json</code>. Die genaue Formel wurde am lokalen Stand geprüft.</li></ul><p><a href="living-world.html">Bestehende Living-World-Dokumentation</a> · <a href="living-world-social-taxonomy.json" download>Alle 600 Einträge als JSON</a> · <a href="/living.html">Vivarium öffnen</a></p></section>
'''

CSS = r'''
:root{--ink:#3e3449;--muted:#766a7b;--violet:#82609c;--paper:#fcfaf5;--line:#e9e0ea;--sage:#6f967e}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:50px 38px 100px}header{padding:35px 0 50px}.kicker{letter-spacing:.18em;font-size:12px;font-weight:700;color:var(--violet)}h1{font-size:clamp(34px,5.3vw,72px);line-height:1.1;letter-spacing:-.04em;margin:20px 0}.lead{font-size:21px;max-width:850px;color:var(--muted)}h2{font-size:30px;line-height:1.3}h3{font-size:20px;margin-top:32px}section{padding:34px 0;border-top:1px solid var(--line);scroll-margin-top:25px}p{max-width:1050px}a{color:#805aa0;text-underline-offset:3px}nav{display:flex;flex-wrap:wrap;gap:10px;padding-bottom:26px}nav a,.badges span{background:#efe8f3;border-radius:100px;padding:7px 14px;font-size:13px;text-decoration:none}.badges{display:flex;flex-wrap:wrap;gap:8px}.badges span{background:#edf2eb;color:#597c63}.callout{background:#f0e9f4;border-left:4px solid #b195c4;padding:20px 24px;border-radius:0 18px 18px 0;margin:28px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.grid article{border:1px solid var(--line);border-radius:18px;padding:10px 22px;background:#fff}.grid p{font-size:14px}.flow{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.flow span{border:1px solid #cfdbcf;background:#eef4ed;border-radius:13px;padding:10px 16px;font-size:14px}.flow b{color:var(--sage)}pre{overflow:auto;background:#f1edf3;border-radius:15px;padding:22px;font:13px/1.8 ui-monospace,monospace;max-width:100%}code{font-size:.9em;background:#f2edf4;border-radius:5px;padding:2px 4px;overflow-wrap:anywhere}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:16px;margin:22px 0;background:#fff}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.65}th,td{padding:16px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}th{background:#f0eaf4;color:#6e547f;font-weight:700}tbody tr:nth-child(even){background:#fcfafc}tbody tr:last-child td{border-bottom:0}.catalog table{min-width:1800px;table-layout:fixed}.catalog th:first-child{width:210px}.catalog th:nth-child(2){width:280px}.catalog th:nth-child(5){width:320px}.catalog td{overflow-wrap:anywhere}.catalog b{display:block}.catalog small{display:block;color:var(--muted);margin-top:5px}.tag{display:inline-block;background:#edf3ec;color:#64826b;border-radius:7px;padding:3px 7px;font-size:11px;margin:6px 0}.tag.conflict{background:#faeee8;color:#a86d52}.filters,.calculator{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:20px;background:#f3eef5;border-radius:17px}.filters button{grid-column:1/-1;justify-self:start}label{display:block;font-size:13px;color:#725f7e}input,select,button{font:inherit;border:1px solid #d9cbdf;border-radius:9px;padding:10px 12px;color:var(--ink);background:#fff}input,select{display:block;width:100%;margin-top:6px}input[type=range]{padding:0;accent-color:var(--violet)}button{cursor:pointer}button:hover{background:#eee5f3}button:disabled{opacity:.4;cursor:default}.pager{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0;font-size:14px}.hint{font-size:13px;color:var(--muted)}details{margin-top:12px;border-top:1px solid var(--line);padding-top:10px}summary{cursor:pointer;color:var(--violet);font-weight:600}.simulator{border:1px solid var(--line);background:#fff;border-radius:22px;padding:24px;max-width:1000px;margin:30px 0}.simulator h3{margin-top:0}.simulator label{margin:14px 0}.barrow{display:grid;grid-template-columns:180px 1fr 50px;gap:12px;align-items:center;font-size:13px;margin-top:10px}.track{background:#eee6f2;height:10px;border-radius:8px;overflow:hidden}.track span{display:block;height:100%;background:#a087b1}#thought-demo{padding:16px;background:#f1f6ef;border-radius:12px;color:#5c7762}.calculator{background:none;padding:0;grid-template-columns:repeat(5,1fr)}:focus-visible{outline:3px solid #bf9dda;outline-offset:3px}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:repeat(2,1fr)}.calculator{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){main{padding:22px 18px 70px}.lead{font-size:17px}.grid{grid-template-columns:1fr}.filters{padding:14px;gap:10px}.pager{font-size:12px}.calculator{grid-template-columns:repeat(2,1fr)}.barrow{grid-template-columns:130px 1fr 40px}.simulator{padding:18px}pre{font-size:11px}}
'''

JS = r'''
const rows=JSON.parse(document.getElementById('data').textContent),categories=JSON.parse(document.getElementById('category-data').textContent),$=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const [id,title]of Object.entries(categories))$('category').insertAdjacentHTML('beforeend',`<option value="${id}">${esc(title)}</option>`);
let page=0,filtered=[];
function render(){const query=$('search').value.trim().toLocaleLowerCase('de'),cat=$('category').value,tone=$('tone').value,size=Number($('page-size').value);filtered=rows.filter(r=>(cat==='all'||r.catalog===cat)&&(tone==='all'||r.tone===tone)&&(!query||(/^[a-f]\d{3}$/i.test(query)?r.id.toLowerCase()===query:JSON.stringify(r).toLocaleLowerCase('de').includes(query))));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/size)-1));const start=page*size;
 $('results').textContent=filtered.length?`${start+1}–${Math.min(start+size,filtered.length)} / ${filtered.length} Einträge · insgesamt ${rows.length}`:'Keine passenden Einträge';$('prev').disabled=!page;$('next').disabled=start+size>=filtered.length;
 $('rows').innerHTML=filtered.slice(start,start+size).map(r=>`<tr id="row-${r.id}"><td><b>${esc(r.id+' · '+r.title)}</b><small>${esc(r.context)}</small><span class="tag ${r.tone==='Konflikt'?'conflict':''}">${esc(r.tone)}</span><small>${esc(r.age)}</small></td><td>${esc(r.description)}<details><summary>Details: Sicht und Dritte</summary><p><b>Was andere über mich denken könnten</b>${esc(r.metabelief)}</p><p><b>Dritte im Raum</b>${esc(r.witnesses)}</p><p><b>Positiver Gegenweg</b>${esc(r.positive)}</p><p><b>Konfliktvariante</b>${esc(r.conflict)}</p>${r.prior_example?`<p>Illustrativer, unkalibrierter Startprior: eigene Hypothese ${r.prior_example.hypothesis}, Alternative ${r.prior_example.alternative}, unbekannt ${r.prior_example.unknown}.</p>`:''}</details></td><td>${esc(r.trigger)}</td><td>${esc(r.resolution)}</td><td><p>${esc(r.expectationA)}</p><p>${esc(r.expectationB)}</p></td><td>${esc(r.effects)}</td><td>${esc(r.w100)}${r.pair?`<p><button data-pair="${r.pair}">Gegenweg ${r.pair} ↗</button></p>`:''}</td></tr>`).join('');
 for(const button of document.querySelectorAll('[data-pair]'))button.onclick=()=>{$('category').value='all';$('tone').value='all';$('search').value=button.dataset.pair;page=0;render();};}
for(const id of ['category','tone','page-size'])$(id).onchange=()=>{page=0;render();};let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{page=0;render();},150);};$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({schema_version:1,status:'design_proposal',categories,entries:rows},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vivarium-social-tom-taxonomy.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function updateBeliefs(){const stress=+$('stress').value/100,rapport=+$('rapport').value/100,e=$('evidence').value;let scores=[Math.log(.35)+stress*.9-rapport*.2,Math.log(.25)+rapport*.65-stress*.2,Math.log(.2),Math.log(.2)];if(e==='agenda')scores[0]+=1.8;if(e==='praise')scores[1]+=2;if(e==='boundary'){scores[2]+=.9;scores[0]-=.6;}const weights=scores.map(s=>Math.exp(s)),sum=weights.reduce((a,b)=>a+b),names=['Aufgabe / Kritik','Anerkennung','Offene Abstimmung','Anderer Anlass'];$('probabilities').innerHTML=weights.map((w,i)=>`<div class="barrow"><span>${names[i]}</span><div class="track"><span style="width:${w/sum*100}%"></span></div><b>${Math.round(w/sum*100)}%</b></div>`).join('');const first=weights.indexOf(Math.max(...weights));$('thought-demo').textContent='„Vielleicht geht es um '+names[first].toLowerCase()+'. Ganz sicher weiß ich das noch nicht. Ich frage nach dem Anlass, bevor ich etwas zusage.“';}
for(const id of ['stress','rapport','evidence'])$(id).oninput=updateBeliefs;
function roundEven(n){const low=Math.floor(n);return n-low===.5?low%2===0?low:low+1:Math.round(n);}
function w100(){const skill=Math.min(99,Math.max(1,+$('skill').value)),attr=Math.min(99,Math.max(1,+$('attribute').value)),pressure=Math.min(28,Math.max(0,+$('pressure').value)),difficulty=Math.min(30,Math.max(-25,+$('difficulty').value)),roll=Math.min(100,Math.max(1,+$('roll').value)),threshold=Math.min(95,Math.max(5,roundEven(.65*skill+.35*attr+9-pressure-difficulty))),grade=roll<=Math.max(1,Math.floor(threshold/5))?'excellent':roll<=threshold?'success':roll>=100-Math.max(1,Math.floor((100-threshold)/6))?'setback':'mixed';$('roll-result').textContent=`Schwelle ${threshold} · Wurf ${roll} → ${grade}. Eine fremde Zustimmung bleibt eine eigenständige Entscheidung.`;}
for(const id of ['skill','attribute','pressure','difficulty','roll'])$(id).oninput=w100;
render();updateBeliefs();w100();
'''

def build():
    duties()
    paired('generations','B',GENERATIONS)
    paired('social','C',SOCIAL)
    paired('romance','D',ROMANCE)
    paired('negotiation','E',NEGOTIATION)
    expectations()
    assert len(ROWS)==600,len(ROWS)
    for category in CATEGORIES:assert sum(r['catalog']==category for r in ROWS)==100,category
    ids={r['id'] for r in ROWS};assert len(ids)==600
    for r in ROWS:
        assert all(r.get(k) for k in ('description','trigger','resolution','effects','expectationA','expectationB','metabelief','witnesses','w100','positive','conflict'))
        if r['pair']:assert r['pair'] in ids
    data={'schema_version':1,'status':'design_proposal','categories':CATEGORIES,'policy':json.loads((ROOT/'config/living_social_policy.json').read_text()),'entries':ROWS}
    (ROOT/'docs/living-world-social-taxonomy.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    encoded=json.dumps(ROWS,ensure_ascii=False,separators=(',',':')).replace('<',chr(92)+'u003c')
    html='<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vivarium · Soziale Interaktionen, Theory of Mind und W100</title><style>'+CSS+'</style></head><body><main>'+OVERVIEW+'</main><script id="data" type="application/json">'+encoded+'</script><script id="category-data" type="application/json">'+json.dumps(CATEGORIES,ensure_ascii=False)+'</script><script>'+JS+'</script></body></html>'
    (ROOT/'docs/living-world-social-tom-plan.html').write_text(html)
    print('Built standalone social/ToM/W100 proposal:',len(ROWS),'entries; HTML',len(html.encode()),'bytes')

if __name__=='__main__':build()
